bash -lc 'set -e; python - << "PY"
path="/src/mruby/src/string.c"
with open(path, "r") as f:
  s = f.read()
start = s.find("static inline mrb_int\nmrb_memsearch_ss(")
if start == -1:
  start = s.find("static inline mrb_int\nmrb_memsearch_ss(")
assert start != -1, "function start not found"
brace = s.find("{", start)
assert brace != -1, "opening brace not found"
depth = 1
pos = brace + 1
while pos < len(s) and depth > 0:
  c = s[pos]
  if c == '{': depth += 1
  elif c == '}': depth -= 1
  pos += 1
end = pos
newblock = '''static inline mrb_int
mrb_memsearch_ss(const unsigned char *xs, long m, const unsigned char *ys, long n)
{
  // Safe, straightforward search to avoid out-of-bounds reads
  if (n < m) return -1;
  const unsigned char *endp = ys + (n - m);
  for (const unsigned char *p = ys; p <= endp; ++p) {
    if (memcmp(p, xs, (size_t)m) == 0) {
      return (mrb_int)(p - ys);
    }
  }
  return -1;
}
'''
s2 = s[:start] + newblock + s[end:]
with open(path, 'w') as f:
  f.write(s2)
print("patched")
PY'

bash -lc 'set -e; python - << "PY" 
path="/src/mruby/src/string.c"
text=open(path, "r", encoding="utf-8").read()
anchor = "static inline mrb_int\nmrb_memsearch_ss("
pos = text.find(anchor)
assert pos != -1, "anchor not found"
brace = text.find("{", pos)
assert brace != -1, "opening brace not found"
depth = 0
i = brace
end = None
while i < len(text):
  c = text[i]
  if c == '{':
    depth += 1
  elif c == '}':
    depth -= 1
    if depth == 0:
      end = i+1
      break
  i += 1
assert end is not None, "end of function not found"
new_block = '''static inline mrb_int
mrb_memsearch_ss(const unsigned char *xs, long m, const unsigned char *ys, long n)
{
  // Safe, straightforward substring search to avoid out-of-bounds reads
  if (n < m) return -1;
  for (long i = 0; i <= n - m; ++i) {
    if (memcmp(xs, ys + i, (size_t)m) == 0) {
      return (mrb_int)i;
    }
  }
  return -1;
}
'''
new_text = text[:pos] + new_block + text[end:]
open(path, 'w', encoding='utf-8').write(new_text)
print("patched")
PY'

